import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Boxes, DollarSign, UserCircle, AlertTriangle, PlusCircle, CheckCircle } from 'lucide-react';

const initialInventory = [
  { id: 1, name: 'Organic Strawberries', stock: 12, unit: 'pint', price: 6.00, lowStock: true },
  { id: 2, name: 'Honeycrisp Apples', stock: 8, unit: 'lb', price: 3.50, lowStock: true },
  { id: 3, name: 'Rainbow Chard', stock: 35, unit: 'bunch', price: 4.00, lowStock: false },
  { id: 4, name: 'Free-Range Eggs', stock: 24, unit: 'dozen', price: 7.50, lowStock: false },
  { id: 5, name: 'Sourdough Loaf', stock: 18, unit: 'each', price: 9.00, lowStock: false },
];

export default function MarketOSPrototype() {
  const [currentScreen, setCurrentScreen] = useState('dashboard');
  const [inventory, setInventory] = useState(initialInventory);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [newProduct, setNewProduct] = useState({ name: 'Heirloom Cherry Tomatoes', price: '4.50', stock: '30', unit: 'lb' });

  const lowStockCount = inventory.filter(item => item.lowStock).length;

  const handleAddProduct = (e) => {
    e.preventDefault();
    const newId = Math.max(...inventory.map(i => i.id)) + 1;
    const productToAdd = {
      id: newId,
      name: newProduct.name,
      stock: parseInt(newProduct.stock, 10),
      unit: newProduct.unit,
      price: parseFloat(newProduct.price),
      lowStock: false,
    };
    setInventory([productToAdd, ...inventory]);
    setCurrentScreen('inventory');
    setShowConfirmation(true);
    setNewProduct({ name: '', price: '', stock: '', unit: 'lb' });
  };

  useEffect(() => {
    if (showConfirmation) {
      const timer = setTimeout(() => setShowConfirmation(false), 4000);
      return () => clearTimeout(timer);
    }
  }, [showConfirmation]);

  const ScreenContent = () => {
    switch (currentScreen) {
      case 'inventory':
        return <InventoryScreen inventory={inventory} setCurrentScreen={setCurrentScreen} showConfirmation={showConfirmation} />;
      case 'addProduct':
        return <AddProductScreen newProduct={newProduct} setNewProduct={setNewProduct} handleAddProduct={handleAddProduct} setCurrentScreen={setCurrentScreen} />;
      case 'sales':
        return <PlaceholderScreen title="Sales Tracking" />;
      case 'account':
        return <PlaceholderScreen title="Account Settings" />;
      default:
        return <DashboardScreen lowStockCount={lowStockCount} setCurrentScreen={setCurrentScreen} />;
    }
  };

  return (
    <div className="w-full max-w-sm mx-auto bg-slate-50 font-sans antialiased shadow-2xl rounded-2xl border border-slate-200 overflow-hidden" style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <div className="h-[736px] flex flex-col">
        <main className="flex-1 overflow-y-auto p-6 space-y-6">
          <ScreenContent />
        </main>
        <BottomNav currentScreen={currentScreen} setCurrentScreen={setCurrentScreen} />
      </div>
    </div>
  );
}

const DashboardScreen = ({ lowStockCount, setCurrentScreen }) => (
  <div className="space-y-6 animate-fade-in">
    <div>
      <p className="text-sm text-slate-500">Rodriguez Family Farm</p>
      <h1 className="text-2xl font-bold text-slate-800">Welcome back, Maria!</h1>
    </div>

    <div className="grid grid-cols-2 gap-4">
      <div className="bg-white p-4 rounded-lg shadow-sm border border-slate-200">
        <p className="text-sm font-medium text-slate-500">Today's Sales</p>
        <p className="text-2xl font-semibold text-slate-800">$347.50</p>
      </div>
      <div className="bg-white p-4 rounded-lg shadow-sm border border-slate-200">
        <p className="text-sm font-medium text-slate-500">Weekly Revenue</p>
        <p className="text-2xl font-semibold text-slate-800">$1,280.00</p>
      </div>
    </div>

    <div 
      className="bg-amber-50 border-l-4 border-amber-400 p-4 rounded-md shadow-sm cursor-pointer hover:shadow-md hover:bg-amber-100 transition-all duration-200"
      onClick={() => setCurrentScreen('inventory')}
    >
      <div className="flex items-center space-x-3">
        <AlertTriangle className="h-6 w-6 text-amber-500" />
        <div>
          <h2 className="font-semibold text-amber-800">Inventory Alert</h2>
          <p className="text-sm text-amber-700">{lowStockCount} items are running low.</p>
        </div>
      </div>
    </div>

    <div className="space-y-3">
        <h2 className="text-lg font-semibold text-slate-700">Quick Actions</h2>
        <button className="w-full bg-green-700 text-white font-bold py-3 px-4 rounded-lg shadow-sm hover:bg-green-800 transition-colors duration-200 flex items-center justify-center space-x-2">
            <DollarSign className="h-5 w-5" />
            <span>Start New Sale</span>
        </button>
        <button 
            onClick={() => setCurrentScreen('addProduct')}
            className="w-full bg-white text-slate-700 font-bold py-3 px-4 rounded-lg shadow-sm border border-slate-300 hover:bg-slate-50 transition-colors duration-200 flex items-center justify-center space-x-2">
            <PlusCircle className="h-5 w-5" />
            <span>Add New Product</span>
        </button>
    </div>
  </div>
);

const InventoryScreen = ({ inventory, setCurrentScreen, showConfirmation }) => (
  <div className="space-y-4 animate-fade-in">
    {showConfirmation && (
      <div className="bg-green-100 border-l-4 border-green-500 text-green-800 p-4 rounded-md flex items-center space-x-3 shadow-sm animate-fade-in-down">
        <CheckCircle className="h-5 w-5" />
        <p className="text-sm font-medium">Product added successfully!</p>
      </div>
    )}
    <div className="flex justify-between items-center">
      <h1 className="text-2xl font-bold text-slate-800">Inventory</h1>
      <button onClick={() => setCurrentScreen('addProduct')} className="bg-green-700 text-white p-2 rounded-full shadow-sm hover:bg-green-800 transition-all duration-200">
        <PlusCircle className="h-5 w-5" />
      </button>
    </div>
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 divide-y divide-slate-200">
      {inventory.map(item => (
        <div key={item.id} className="p-4 flex items-center justify-between">
          <div>
            <p className="font-semibold text-slate-800">{item.name}</p>
            <p className="text-sm text-slate-500">${item.price.toFixed(2)} / {item.unit}</p>
          </div>
          <div className={`text-right ${item.lowStock ? 'text-red-600' : 'text-slate-600'}`}>
            <p className="font-bold text-lg">{item.stock}</p>
            <p className="text-xs">in stock</p>
          </div>
        </div>
      ))}
    </div>
  </div>
);

const AddProductScreen = ({ newProduct, setNewProduct, handleAddProduct, setCurrentScreen }) => (
    <div className="space-y-6 animate-fade-in">
        <div>
            <h1 className="text-2xl font-bold text-slate-800">Add New Product</h1>
            <p className="text-sm text-slate-500">Enter the details for your new item.</p>
        </div>
        <form onSubmit={handleAddProduct} className="space-y-5">
            <div>
                <label htmlFor="productName" className="block text-sm font-medium text-slate-700 mb-1">Product Name</label>
                <input type="text" id="productName" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:ring-green-500 focus:border-green-500" required />
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label htmlFor="price" className="block text-sm font-medium text-slate-700 mb-1">Price</label>
                    <div className="relative">
                        <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-slate-500">$</span>
                        <input type="number" id="price" value={newProduct.price} onChange={e => setNewProduct({...newProduct, price: e.target.value})} className="w-full pl-7 pr-3 py-2 border border-slate-300 rounded-md shadow-sm focus:ring-green-500 focus:border-green-500" step="0.01" required />
                    </div>
                </div>
                 <div>
                    <label htmlFor="stock" className="block text-sm font-medium text-slate-700 mb-1">Initial Stock</label>
                    <input type="number" id="stock" value={newProduct.stock} onChange={e => setNewProduct({...newProduct, stock: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:ring-green-500 focus:border-green-500" required />
                </div>
            </div>
             <div>
                <label htmlFor="unit" className="block text-sm font-medium text-slate-700 mb-1">Unit</label>
                <select id="unit" value={newProduct.unit} onChange={e => setNewProduct({...newProduct, unit: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:ring-green-500 focus:border-green-500 bg-white">
                    <option>lb</option>
                    <option>pint</option>
                    <option>bunch</option>
                    <option>each</option>
                    <option>dozen</option>
                </select>
            </div>
            <div className="flex items-center space-x-4 pt-4">
                <button type="button" onClick={() => setCurrentScreen('inventory')} className="w-full text-center bg-white text-slate-700 font-bold py-3 px-4 rounded-lg shadow-sm border border-slate-300 hover:bg-slate-50 transition-colors duration-200">Cancel</button>
                <button type="submit" className="w-full text-center bg-green-700 text-white font-bold py-3 px-4 rounded-lg shadow-sm hover:bg-green-800 transition-colors duration-200">Save Product</button>
            </div>
        </form>
    </div>
);

const PlaceholderScreen = ({ title }) => (
    <div className="text-center py-20 animate-fade-in">
        <h1 className="text-2xl font-bold text-slate-800">{title}</h1>
        <p className="text-slate-500 mt-2">This feature is coming soon.</p>
    </div>
);

const BottomNav = ({ currentScreen, setCurrentScreen }) => {
  const navItems = [
    { id: 'dashboard', icon: LayoutDashboard, label: 'Dashboard' },
    { id: 'inventory', icon: Boxes, label: 'Inventory' },
    { id: 'sales', icon: DollarSign, label: 'Sales' },
    { id: 'account', icon: UserCircle, label: 'Account' },
  ];

  return (
    <nav className="bg-white border-t border-slate-200 shadow-inner">
      <div className="flex justify-around py-2">
        {navItems.map(item => (
          <button 
            key={item.id}
            onClick={() => setCurrentScreen(item.id)}
            className={`flex flex-col items-center justify-center w-1/4 p-2 rounded-lg transition-all duration-200 ${currentScreen === item.id ? 'text-green-700' : 'text-slate-500 hover:bg-slate-100'}`}
          >
            <item.icon className="h-6 w-6 mb-1" />
            <span className={`text-xs font-medium ${currentScreen === item.id ? 'font-bold' : ''}`}>{item.label}</span>
          </button>
        ))}
      </div>
    </nav>
  );
};
